3	const BASE_PREMIUMS: Record<string, number> = {
4	  sword: 100,
5	};
6	
7	const COMPONENT_BASE_PREMIUM = 25;
8	const COMPONENT_BLOCK_SIZE = 3;
9	const COMPONENT_BLOCK_PREMIUM = 60;
10	const COMPONENT_TYPES = new Set(["rune"]);
11	
12	const FIRST_INSURANCE_SURCHARGE = 0.1;
13	
14	interface Item {
15	  type: string;
16	}
17	
18	interface QuoteStep {
19	  op: "quote";
20	  items: Item[];
21	}
22	
23	interface Scenario {
24	  customer: { yearsWithMHPCO: number };
25	  steps: QuoteStep[];
26	}
27	
28	interface QuoteResult {
29	  premium: number;
30	}
31	
32	interface ScenarioResult {
33	  results: QuoteResult[];
34	}
