36	const componentGroupBase = (count: number): number =>
37	  count === COMPONENT_BLOCK_SIZE
38	    ? COMPONENT_BLOCK_PREMIUM
39	    : count * COMPONENT_BASE_PREMIUM;
40	
41	const countByType = (items: Item[]): Map<string, number> => {
42	  const counts = new Map<string, number>();
43	  for (const item of items) {
44	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
45	  }
46	  return counts;
47	};
48	
49	const itemBasePremiums = (items: Item[]): number[] => {
50	  const mainItems = items.filter((item) => !COMPONENT_TYPES.has(item.type));
51	  const components = items.filter((item) => COMPONENT_TYPES.has(item.type));
52	
53	  const mainBases = mainItems.map((item) => BASE_PREMIUMS[item.type]);
54	  const componentBases = [...countByType(components).values()].map(
55	    componentGroupBase,
56	  );
57	
58	  return [...mainBases, ...componentBases];
59	};
60	
61	const quotePremium = (items: Item[]): number => {
62	  const bases = itemBasePremiums(items);
63	  const itemsTotal = bases.reduce(
64	    (sum, base) => sum + base + base * FIRST_INSURANCE_SURCHARGE,
65	    0,
66	  );
67	  return Math.ceil(itemsTotal + PROCESSING_FEE);
68	};
69	
70	export const runScenario = (scenario: Scenario): ScenarioResult => {
71	  const results = scenario.steps.map((step) => ({ premium: quotePremium(step.items) }));
72	  return { results };
73	};
